-- Standalone HRMS schema. This migration is the complete initial state for an empty PostgreSQL database.
-- Runtime seed data is created idempotently by DataSeeder using APP_SEED_* settings.

CREATE TABLE company (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0,
    created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by VARCHAR(100), updated_by VARCHAR(100), deleted BOOLEAN NOT NULL DEFAULT FALSE,
    deleted_at TIMESTAMP(6) WITHOUT TIME ZONE, name VARCHAR(255) NOT NULL, domain VARCHAR(255),
    productive_threshold_percent INTEGER DEFAULT 80, neutral_threshold_percent INTEGER DEFAULT 50
);

CREATE TABLE role (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100),
    deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE,
    name VARCHAR(60) NOT NULL UNIQUE, label VARCHAR(100), description VARCHAR(300), system_defined BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE TABLE permission (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100),
    deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE,
    code VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(300), module VARCHAR(100)
);
CREATE TABLE role_permissions (
    role_id BIGINT NOT NULL REFERENCES role(id), permission_id BIGINT NOT NULL REFERENCES permission(id),
    PRIMARY KEY (role_id, permission_id)
);
CREATE TABLE app_user (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100),
    deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE,
    username VARCHAR(100) NOT NULL UNIQUE, email VARCHAR(150) NOT NULL UNIQUE, full_name VARCHAR(150) NOT NULL,
    password_hash VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, must_change_password BOOLEAN NOT NULL DEFAULT FALSE,
    last_login_at TIMESTAMP(6) WITHOUT TIME ZONE, failed_login_attempts INTEGER NOT NULL DEFAULT 0,
    locked_until TIMESTAMP(6) WITHOUT TIME ZONE, company_id BIGINT REFERENCES company(id)
);
CREATE TABLE user_roles (
    user_id BIGINT NOT NULL REFERENCES app_user(id), role_id BIGINT NOT NULL REFERENCES role(id), PRIMARY KEY (user_id, role_id)
);

CREATE TABLE department (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100),
    deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE,
    name VARCHAR(150) NOT NULL, code VARCHAR(20) NOT NULL UNIQUE, description VARCHAR(500),
    parent_department_id BIGINT REFERENCES department(id), head_employee_id BIGINT, active BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE TABLE designation (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100),
    deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE,
    title VARCHAR(150) NOT NULL, level INTEGER, department_id BIGINT REFERENCES department(id), active BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE TABLE team (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100),
    deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE,
    name VARCHAR(150) NOT NULL, department_id BIGINT REFERENCES department(id), lead_employee_id BIGINT, active BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE TABLE employee (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100),
    deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE,
    employee_id VARCHAR(20) NOT NULL UNIQUE, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL,
    email VARCHAR(255) NOT NULL UNIQUE, phone VARCHAR(30), date_of_birth DATE, gender VARCHAR(30), date_of_joining DATE NOT NULL,
    employment_type VARCHAR(20) NOT NULL DEFAULT 'FULL_TIME', employment_status VARCHAR(30) NOT NULL DEFAULT 'Active',
    department_id BIGINT REFERENCES department(id), designation_id BIGINT REFERENCES designation(id), team_id BIGINT REFERENCES team(id),
    reporting_manager_id BIGINT REFERENCES employee(id), user_id BIGINT REFERENCES app_user(id), company_id BIGINT REFERENCES company(id),
    address VARCHAR(300), emergency_contact_name VARCHAR(150), emergency_contact_phone VARCHAR(30), profile_photo_url VARCHAR(500),
    biometric_device_user_id VARCHAR(30) UNIQUE
);

CREATE TABLE leave_type (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100),
    deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE,
    company_id BIGINT REFERENCES company(id), name VARCHAR(100) NOT NULL, code VARCHAR(20) NOT NULL UNIQUE,
    default_days_per_year DOUBLE PRECISION NOT NULL DEFAULT 0, carry_forward BOOLEAN NOT NULL DEFAULT FALSE, active BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE TABLE leave_balance (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100),
    deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE,
    company_id BIGINT REFERENCES company(id), employee_id BIGINT NOT NULL REFERENCES employee(id), leave_type_id BIGINT NOT NULL REFERENCES leave_type(id),
    "year" INTEGER NOT NULL, allocated_days DOUBLE PRECISION NOT NULL DEFAULT 0, carried_forward_days DOUBLE PRECISION NOT NULL DEFAULT 0,
    UNIQUE(employee_id, leave_type_id, "year")
);
CREATE TABLE leave_request (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100),
    deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE,
    company_id BIGINT REFERENCES company(id), employee_id BIGINT NOT NULL REFERENCES employee(id), leave_type_id BIGINT NOT NULL REFERENCES leave_type(id),
    start_date DATE NOT NULL, end_date DATE NOT NULL, days DOUBLE PRECISION NOT NULL DEFAULT 0, reason VARCHAR(500), status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    decided_by_employee_id BIGINT REFERENCES employee(id), decided_at TIMESTAMP(6) WITHOUT TIME ZONE, decision_note VARCHAR(500)
);
CREATE TABLE holiday (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100),
    deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE,
    company_id BIGINT REFERENCES company(id), name VARCHAR(150) NOT NULL, date DATE NOT NULL
);

CREATE TABLE biometric_device (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100),
    deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE,
    serial_number VARCHAR(50) NOT NULL UNIQUE, device_name VARCHAR(100) NOT NULL, last_ip_address VARCHAR(50), last_seen_at TIMESTAMP(6) WITHOUT TIME ZONE,
    push_version VARCHAR(50), company_id BIGINT REFERENCES company(id)
);
CREATE TABLE attendance_record (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100),
    deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE,
    employee_id VARCHAR(20) REFERENCES employee(employee_id), company_id BIGINT REFERENCES company(id), device_user_id VARCHAR(30) NOT NULL,
    employee_name VARCHAR(255) NOT NULL, punch_time TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL, punch_type VARCHAR(10) NOT NULL,
    verify_mode VARCHAR(30), device_serial_number VARCHAR(50) NOT NULL, device_name VARCHAR(100) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'RECEIVED', raw_line VARCHAR(500),
    CONSTRAINT uk_attendance_dedupe UNIQUE(device_serial_number, device_user_id, punch_time)
);
CREATE TABLE work_session (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100),
    deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE,
    employee_id BIGINT REFERENCES employee(id), company_id BIGINT REFERENCES company(id), session_date DATE NOT NULL,
    login_time TIMESTAMP(6) WITHOUT TIME ZONE, logout_time TIMESTAMP(6) WITHOUT TIME ZONE, working_mode VARCHAR(20) NOT NULL,
    status VARCHAR(20) NOT NULL, total_working_minutes INTEGER
);

CREATE TABLE monitored_device (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100),
    deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE,
    device_id VARCHAR(100) NOT NULL UNIQUE, device_name VARCHAR(150) NOT NULL, windows_username VARCHAR(150), domain_name VARCHAR(150),
    ip_address VARCHAR(50), mac_address VARCHAR(50), hostname VARCHAR(150), serial_number VARCHAR(150), assigned_date DATE,
    machine_guid VARCHAR(100), operating_system VARCHAR(100), os_version VARCHAR(50), agent_version VARCHAR(50),
    agent_token_hash VARCHAR(200) NOT NULL UNIQUE, employee_id BIGINT REFERENCES employee(id), company_id BIGINT REFERENCES company(id),
    status VARCHAR(20) NOT NULL DEFAULT 'OFFLINE', current_application VARCHAR(255), current_window_title VARCHAR(500),
    last_seen_at TIMESTAMP(6) WITHOUT TIME ZONE, last_ip_address VARCHAR(50), active BOOLEAN NOT NULL DEFAULT TRUE,
    heartbeat_interval_seconds INTEGER, monitoring_paused BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE TABLE activity_session (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100),
    deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE,
    session_id VARCHAR(40) NOT NULL UNIQUE, device_id BIGINT NOT NULL REFERENCES monitored_device(id), employee_id BIGINT REFERENCES employee(id), company_id BIGINT REFERENCES company(id),
    process_name VARCHAR(255), application_name VARCHAR(255), window_title VARCHAR(500), start_time TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    end_time TIMESTAMP(6) WITHOUT TIME ZONE, duration_seconds INTEGER NOT NULL DEFAULT 0, is_idle_session BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE TABLE otp_verification (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    company_id BIGINT REFERENCES company(id), device_id BIGINT REFERENCES monitored_device(id), requested_by_user_id BIGINT REFERENCES app_user(id),
    otp_hash VARCHAR(512) NOT NULL, salt VARCHAR(128) NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL DEFAULT 5,
    resend_count INTEGER NOT NULL DEFAULT 0, last_resend_at TIMESTAMP(6) WITHOUT TIME ZONE, expires_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL,
    used BOOLEAN NOT NULL DEFAULT FALSE, used_at TIMESTAMP(6) WITHOUT TIME ZONE,
    created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE TABLE token_rotation_history (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    company_id BIGINT REFERENCES company(id), device_id BIGINT REFERENCES monitored_device(id), rotated_by_user_id BIGINT REFERENCES app_user(id),
    previous_agent_token_hash VARCHAR(512), new_agent_token_hash VARCHAR(512), rotation_reason VARCHAR(255), rotation_ip VARCHAR(64),
    created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE audit_log (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, entity_name VARCHAR(100) NOT NULL, entity_id BIGINT NOT NULL,
    company_id BIGINT REFERENCES company(id), action VARCHAR(50) NOT NULL, performed_by VARCHAR(100) NOT NULL,
    performed_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, ip_address VARCHAR(50), details VARCHAR(1000)
);
CREATE TABLE login_history (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(100) NOT NULL, success BOOLEAN NOT NULL,
    failure_reason VARCHAR(200), ip_address VARCHAR(50), user_agent VARCHAR(300), attempted_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE refresh_token (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES app_user(id), token_hash VARCHAR(200) NOT NULL UNIQUE,
    expires_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE, revoked_at TIMESTAMP(6) WITHOUT TIME ZONE,
    created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by_ip VARCHAR(50), user_agent VARCHAR(300)
);

CREATE TABLE goal (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100), deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE, employee_id BIGINT NOT NULL REFERENCES employee(id), company_id BIGINT REFERENCES company(id), title VARCHAR(200) NOT NULL, description VARCHAR(1000), target_date DATE, status VARCHAR(20) NOT NULL DEFAULT 'NOT_STARTED', progress_percent INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE performance_review (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100), deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE, employee_id BIGINT NOT NULL REFERENCES employee(id), reviewer_employee_id BIGINT REFERENCES employee(id), company_id BIGINT REFERENCES company(id), review_period VARCHAR(50) NOT NULL, rating INTEGER, strengths VARCHAR(2000), areas_for_improvement VARCHAR(2000), status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', submitted_at TIMESTAMP(6) WITHOUT TIME ZONE
);
CREATE TABLE job_opening (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100), deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE, company_id BIGINT REFERENCES company(id), title VARCHAR(150) NOT NULL, department_id BIGINT REFERENCES department(id), designation_id BIGINT REFERENCES designation(id), employment_type VARCHAR(20) NOT NULL DEFAULT 'FULL_TIME', openings_count INTEGER NOT NULL DEFAULT 1, status VARCHAR(20) NOT NULL DEFAULT 'OPEN', description VARCHAR(2000), posted_date DATE, closed_date DATE, recruiter_id BIGINT REFERENCES employee(id), closed_reason VARCHAR(80), closed_comments VARCHAR(1000), closed_by VARCHAR(100), closed_at TIMESTAMP(6) WITHOUT TIME ZONE
);
CREATE TABLE candidate (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100), deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL, phone VARCHAR(30), job_opening_id BIGINT NOT NULL REFERENCES job_opening(id), source VARCHAR(100), resume_url VARCHAR(500), resume_file_key VARCHAR(300), resume_original_name VARCHAR(255), experience_years DOUBLE PRECISION, skills VARCHAR(500), stage VARCHAR(20) NOT NULL DEFAULT 'APPLIED', applied_date DATE NOT NULL, offer_amount DOUBLE PRECISION, expected_joining_date DATE, notes VARCHAR(1000), rating INTEGER, remarks VARCHAR(1000), rejection_reason VARCHAR(500), offer_generated_at TIMESTAMP(6) WITHOUT TIME ZONE, offer_accepted_at TIMESTAMP(6) WITHOUT TIME ZONE, created_employee_id BIGINT REFERENCES employee(id), offer_letter_file_key VARCHAR(300), offer_letter_original_name VARCHAR(255), offer_letter_uploaded_at TIMESTAMP(6) WITHOUT TIME ZONE, offer_letter_uploaded_by VARCHAR(150), offer_letter_sent_at TIMESTAMP(6) WITHOUT TIME ZONE, offer_letter_email_status VARCHAR(20)
);
CREATE TABLE interview (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100), deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE, candidate_id BIGINT NOT NULL REFERENCES candidate(id), interviewer_employee_id BIGINT REFERENCES employee(id), scheduled_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL, mode VARCHAR(20) NOT NULL DEFAULT 'VIDEO', status VARCHAR(20) NOT NULL DEFAULT 'SCHEDULED', rating INTEGER, feedback VARCHAR(1000), round_number INTEGER NOT NULL DEFAULT 1, round_type VARCHAR(30) DEFAULT 'HR_INTERVIEW', meeting_link VARCHAR(500), technical_rating INTEGER, communication_rating INTEGER, instructions VARCHAR(1000), decision VARCHAR(30)
);
CREATE TABLE employee_document (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100), deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE, employee_id BIGINT NOT NULL REFERENCES employee(id), company_id BIGINT REFERENCES company(id), document_type VARCHAR(40) NOT NULL, document_number VARCHAR(100), issue_date DATE, expiry_date DATE NOT NULL, notes VARCHAR(500)
);
CREATE TABLE salary_structure (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100), deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE, employee_id BIGINT NOT NULL REFERENCES employee(id), company_id BIGINT REFERENCES company(id), effective_from DATE NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, basic_salary NUMERIC(14,2) NOT NULL DEFAULT 0, hra NUMERIC(14,2) NOT NULL DEFAULT 0, special_allowance NUMERIC(14,2) NOT NULL DEFAULT 0, medical_allowance NUMERIC(14,2) NOT NULL DEFAULT 0, travel_allowance NUMERIC(14,2) NOT NULL DEFAULT 0, bonus NUMERIC(14,2) NOT NULL DEFAULT 0, incentives NUMERIC(14,2) NOT NULL DEFAULT 0, overtime NUMERIC(14,2) NOT NULL DEFAULT 0, pf NUMERIC(14,2) NOT NULL DEFAULT 0, esi NUMERIC(14,2) NOT NULL DEFAULT 0, professional_tax NUMERIC(14,2) NOT NULL DEFAULT 0, tds NUMERIC(14,2) NOT NULL DEFAULT 0, other_deductions NUMERIC(14,2) NOT NULL DEFAULT 0, gross_salary NUMERIC(14,2) NOT NULL DEFAULT 0, total_deductions NUMERIC(14,2) NOT NULL DEFAULT 0, net_salary NUMERIC(14,2) NOT NULL DEFAULT 0, notes VARCHAR(1000)
);
CREATE TABLE payroll_run (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100), deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE, company_id BIGINT REFERENCES company(id), period_month INTEGER NOT NULL, period_year INTEGER NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'DRAFT', pay_date DATE, processed_at TIMESTAMP(6) WITHOUT TIME ZONE, total_employees INTEGER NOT NULL DEFAULT 0, total_gross NUMERIC(16,2) NOT NULL DEFAULT 0, total_deductions NUMERIC(16,2) NOT NULL DEFAULT 0, total_net NUMERIC(16,2) NOT NULL DEFAULT 0, remarks VARCHAR(1000)
