CREATE TABLE payroll_item (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100), deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE, payroll_run_id BIGINT NOT NULL REFERENCES payroll_run(id), employee_id BIGINT NOT NULL REFERENCES employee(id), salary_structure_id BIGINT REFERENCES salary_structure(id), company_id BIGINT REFERENCES company(id), basic_salary NUMERIC(14,2) NOT NULL DEFAULT 0, hra NUMERIC(14,2) NOT NULL DEFAULT 0, special_allowance NUMERIC(14,2) NOT NULL DEFAULT 0, medical_allowance NUMERIC(14,2) NOT NULL DEFAULT 0, travel_allowance NUMERIC(14,2) NOT NULL DEFAULT 0, bonus NUMERIC(14,2) NOT NULL DEFAULT 0, incentives NUMERIC(14,2) NOT NULL DEFAULT 0, overtime NUMERIC(14,2) NOT NULL DEFAULT 0, pf NUMERIC(14,2) NOT NULL DEFAULT 0, esi NUMERIC(14,2) NOT NULL DEFAULT 0, professional_tax NUMERIC(14,2) NOT NULL DEFAULT 0, tds NUMERIC(14,2) NOT NULL DEFAULT 0, other_deductions NUMERIC(14,2) NOT NULL DEFAULT 0, gross_salary NUMERIC(14,2) NOT NULL DEFAULT 0, total_deductions NUMERIC(14,2) NOT NULL DEFAULT 0, net_salary NUMERIC(14,2) NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', payment_date DATE, remarks VARCHAR(500)
);
CREATE TABLE requirement (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100), deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE, company_id BIGINT NOT NULL REFERENCES company(id), title VARCHAR(255) NOT NULL, description TEXT, status VARCHAR(20) NOT NULL DEFAULT 'OPEN', assigned_to_user_id BIGINT REFERENCES app_user(id), due_date DATE, close_reason VARCHAR(1000), closed_by BIGINT REFERENCES app_user(id), closed_at TIMESTAMP(6) WITHOUT TIME ZONE
);
CREATE TABLE subscription (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP(6) WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(100), updated_by VARCHAR(100), deleted BOOLEAN NOT NULL DEFAULT FALSE, deleted_at TIMESTAMP(6) WITHOUT TIME ZONE, company_id BIGINT REFERENCES company(id), plan VARCHAR(50) NOT NULL, status VARCHAR(50) NOT NULL, employee_limit INTEGER, device_limit INTEGER, start_date DATE, renewal_date DATE, amount NUMERIC(10,2)
);

CREATE INDEX idx_employee_company ON employee(company_id);
CREATE INDEX idx_attendance_company ON attendance_record(company_id);
CREATE INDEX idx_work_session_employee ON work_session(employee_id);
CREATE INDEX idx_monitored_device_company ON monitored_device(company_id);
CREATE INDEX idx_activity_session_device ON activity_session(device_id);
CREATE INDEX idx_activity_session_employee ON activity_session(employee_id);
CREATE INDEX idx_activity_session_start ON activity_session(start_time);
CREATE INDEX idx_holiday_company_date ON holiday(company_id, date);
CREATE INDEX idx_leave_request_company ON leave_request(company_id);
CREATE INDEX idx_goal_employee ON goal(employee_id);
CREATE INDEX idx_performance_review_employee ON performance_review(employee_id);
CREATE INDEX idx_candidate_job_opening ON candidate(job_opening_id);
CREATE INDEX idx_interview_candidate ON interview(candidate_id);
CREATE INDEX idx_employee_document_employee ON employee_document(employee_id);
CREATE INDEX idx_employee_document_expiry ON employee_document(expiry_date);
CREATE INDEX idx_salary_structure_employee ON salary_structure(employee_id);
CREATE UNIQUE INDEX uq_salary_structure_one_active ON salary_structure(employee_id) WHERE active = TRUE AND deleted = FALSE;
CREATE UNIQUE INDEX uq_payroll_run_period ON payroll_run(period_year, period_month) WHERE deleted = FALSE;
CREATE INDEX idx_payroll_item_run ON payroll_item(payroll_run_id);
CREATE INDEX idx_payroll_item_employee ON payroll_item(employee_id);
CREATE UNIQUE INDEX uq_payroll_item_run_employee ON payroll_item(payroll_run_id, employee_id) WHERE deleted = FALSE;
CREATE INDEX idx_requirement_company_status ON requirement(company_id, status);
CREATE INDEX idx_subscription_company ON subscription(company_id);
